function readCart(){if(!merchProducts.length)initializeMerch();try{return JSON.parse(localStorage.getItem('sso-cart-v1')||'[]').filter(x=>merchProducts.some(p=>p.id===x.id&&p.sizes.includes(x.size))&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=10).slice(0,30)}catch{return []}}
let shoppingBag=null;
function saveCart(){try{localStorage.setItem('sso-cart-v1',JSON.stringify(shoppingBag))}catch{}updateCartCount()}
function updateCartCount(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent='('+shoppingBag.reduce((a,x)=>a+x.quantity,0)+')')}
function addCartItem(id,size){const item=shoppingBag.find(x=>x.id===id&&x.size===size);if(item)item.quantity=Math.min(10,item.quantity+1);else shoppingBag.push({id,size,quantity:1});saveCart()}
function cartRows(){return shoppingBag.map((x,i)=>{const p=merchProducts.find(p=>p.id===x.id);return `<article class="bag-item"><img src="merch/${p.id}-studio.png" alt="${t(p.name)}"><div><h3>${t(p.name)}</h3><p>${tr('Size','المقاس')}: ${x.size==='One size'?tr('One size','مقاس واحد'):x.size}</p><label for="bag-qty-${i}">${tr('Quantity','الكمية')}</label><select id="bag-qty-${i}" data-bag-qty="${i}">${Array.from({length:10},(_,n)=>`<option ${x.quantity===n+1?'selected':''}>${n+1}</option>`).join('')}</select><button type="button" class="textlink" data-bag-remove="${i}">${tr('Remove','إزالة')}</button></div><b>${merchPrice(p.price*x.quantity)}</b></article>`}).join('')}
function bagSubtotal(){return shoppingBag.reduce((s,x)=>s+merchProducts.find(p=>p.id===x.id).price*x.quantity,0)}
function checkoutSection(){if(shoppingBag===null)shoppingBag=readCart();return `<section class="section checkout-section" id="checkout"><a class="textlink" href="/sso-uofa/merch.html">${tr('Back to the collection','العودة للمجموعة')}</a><div class="checkout-heading"><div class="eyebrow">${tr('A little piece of home','حتة من البيت')}</div><h2>${tr('Your bag. Your next favourite.','حقيبتك. قطعتك المفضلة القادمة.')}</h2><p>${tr('Choose your pieces, then review the details.','اختر قطعك ثم راجع التفاصيل.')}</p></div><div id="checkout-empty" ${shoppingBag.length?'hidden':''} class="bag-empty"><h3>${tr('Your bag is waiting for a little Sudan.','حقيبتك تنتظر شوية سودان.')}</h3><p>${tr('Explore the collection and add a piece in your size.','استكشف المجموعة وأضف قطعة بمقاسك.')}</p><a class="button" href="/sso-uofa/merch.html">${tr('Explore the collection','استكشف المجموعة')} </a></div><div class="checkout-layout" id="checkout-content" ${shoppingBag.length?'':'hidden'}><div><div id="bag-items">${cartRows()}</div><form id="checkout-form" class="demoform checkout-details"><div class="eyebrow">01 · ${tr('Your details','بياناتك')}</div><h3>${tr('Who’s picking up?','من سيستلم؟')}</h3><label for="checkout-name">${tr('Full name','الاسم الكامل')}</label><input id="checkout-name" name="name" autocomplete="name" required maxlength="100"><label for="checkout-email">${tr('Email','البريد الإلكتروني')}</label><input id="checkout-email" name="email" type="email" autocomplete="email" required maxlength="254"><div class="pickup-choice"><span class="eyebrow">02 · ${tr('Pickup','الاستلام')}</span><h3>${tr('Meet us on campus.','نلتقي في الجامعة.')}</h3><p>${tr('Campus pickup is planned for this collection. Dates and location will be announced when orders open.','نخطط للاستلام في الجامعة. تُعلن المواعيد والموقع عند فتح الطلبات.')}</p></div><button class="button" type="submit">${tr('Review my order','مراجعة طلبي')} </button><p class="checkout-privacy">${tr('Your details stay on this page and are not sent or saved.','تبقى بياناتك في هذه الصفحة ولا تُرسل أو تُحفظ.')}</p></form><div id="checkout-review" class="checkout-review" hidden aria-live="polite"></div></div><aside class="checkout-summary"><div class="eyebrow">${tr('The details','التفاصيل')}</div><h3>${tr('Order summary','ملخص الطلب')}</h3><div class="summary-line"><span>${tr('Estimated subtotal','المجموع التقديري')}</span><b id="bag-subtotal">${merchPrice(bagSubtotal())}</b></div><p>${tr('Prices are estimates in CAD. Final pricing, any applicable taxes and pickup arrangements will be confirmed before ordering opens.','الأسعار تقديرية بالدولار الكندي. تُحدد الأسعار النهائية والضرائب المطبقة وترتيبات الاستلام قبل فتح الطلبات.')}</p><div class="checkout-availability"><b>${tr('Orders opening soon','الطلبات تُفتح قريباً')}</b><p>${tr('You can build your bag and review it here. Checkout is not accepting payments or placing orders yet.','يمكنك تجهيز حقيبتك ومراجعتها هنا. لا نقبل المدفوعات أو ننشئ طلبات بعد.')}</p></div><a class="textlink" href="/sso-uofa/contact.html">${tr('Have a question?','عندك سؤال؟')} </a></aside></div></section>`}
function refreshBag(){document.querySelector('#bag-items').innerHTML=cartRows();document.querySelector('#bag-subtotal').textContent=merchPrice(bagSubtotal());document.querySelector('#checkout-empty').hidden=!!shoppingBag.length;document.querySelector('#checkout-content').hidden=!shoppingBag.length;document.querySelector('#checkout-review').hidden=true;saveCart();bindBagControls()}
function bindBagControls(){document.querySelectorAll('[data-bag-qty]').forEach(e=>e.onchange=()=>{shoppingBag[Number(e.dataset.bagQty)].quantity=Number(e.value);refreshBag()});document.querySelectorAll('[data-bag-remove]').forEach(e=>e.onclick=()=>{shoppingBag.splice(Number(e.dataset.bagRemove),1);refreshBag()})}
function bindCheckout(){updateCartCount();bindBagControls();document.querySelector('#checkout-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#checkout-name').value.trim(),email=document.querySelector('#checkout-email').value.trim();if(!name){document.querySelector('#checkout-name').setCustomValidity(tr('Please enter your name.','أدخل اسمك.'));document.querySelector('#checkout-name').reportValidity();return}const box=document.querySelector('#checkout-review');box.innerHTML=`<div class="eyebrow">03 · ${tr('Review','المراجعة')}</div><h3>${tr('Your bag is ready to review.','حقيبتك جاهزة للمراجعة.')}</h3><p><b>${escapeOnboard(name)}</b><br>${escapeOnboard(email)}</p><ul>${shoppingBag.map(x=>`<li>${escapeOnboard(t(merchProducts.find(p=>p.id===x.id).name))} · ${x.size} × ${x.quantity}</li>`).join('')}</ul><p><b>${tr('Estimated subtotal','المجموع التقديري')}: ${merchPrice(bagSubtotal())}</b></p><p>${tr('No order has been placed. We’ll announce when orders open; you can return to your saved bag then.','لم يُنشأ طلب. سنعلن عند فتح الطلبات؛ يمكنك العودة لحقيبتك المحفوظة حينها.')}</p><button class="button light" id="checkout-edit" type="button">${tr('Edit details','تعديل البيانات')}</button>`;box.hidden=false;document.querySelector('#checkout-edit').onclick=()=>{box.hidden=true;document.querySelector('#checkout-name').focus()};box.scrollIntoView({behavior:'smooth',block:'center'})};document.querySelector('#checkout-name').oninput=e=>e.target.setCustomValidity('')}
